@push('scripts')
<script>
(()=>{if(window.priestAgendaChatTimer)clearInterval(window.priestAgendaChatTimer);const root=document.getElementById('chat');if(!root)return;const list=document.getElementById('conversation'),form=document.getElementById('chat-form'),input=document.getElementById('chat-body'),uid=Number(root.dataset.userId);let last=Math.max(0,...[...list.querySelectorAll('[data-message-id]')].map(el=>Number(el.dataset.messageId)));let busy=false;
const append=m=>{if(list.querySelector('[data-message-id="'+m.id+'"]'))return;list.querySelector('.chat-empty')?.remove();const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<100;const bubble=document.createElement('div');bubble.className='bubble'+(Number(m.sender_id)===uid?' mine':'');bubble.dataset.messageId=m.id;const who=document.createElement('strong');who.textContent=m.sender;const text=document.createElement('div');text.textContent=m.body;const time=document.createElement('small');time.textContent=m.created_at;bubble.append(who,text,time);list.append(bubble);last=Math.max(last,Number(m.id));if(nearBottom)list.scrollTop=list.scrollHeight;};
const poll=async()=>{if(busy||document.hidden)return;try{const r=await fetch(root.dataset.updatesUrl+'?after='+last,{headers:{Accept:'application/json'},credentials:'same-origin'});if(r.ok){const d=await r.json();d.messages.forEach(append)}}catch(e){}};
form.addEventListener('submit',async e=>{e.preventDefault();if(!input.value.trim())return;const button=document.getElementById('send-message');button.disabled=true;try{const body=new FormData(form);const r=await fetch(form.action,{method:'POST',body,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});if(r.ok){const m=await r.json();append(m);input.value='';input.focus()}else if(r.status===429){alert('{{ __('ui.too_many_messages') }}')}}catch(e){}finally{button.disabled=false}});
list.scrollTop=list.scrollHeight;window.priestAgendaChatTimer=setInterval(poll,2000);
})();
</script>
